import React from 'react';
import { useEditorialMotion } from '../hooks/useEditorialMotion';
import portfolioContent from '../content/portfolioContent';
import OpeningSpread from './editorial/OpeningSpread';
import SectionShell from './editorial/SectionShell';
import SelectedWork from './editorial/SelectedWork';
import ExperienceTimeline from './editorial/ExperienceTimeline';

export default function EditorialPortfolio() {
  useEditorialMotion();

  const { identity, selectedWork, experience, education, leadership, contact } = portfolioContent;

  return (
    <>
      {/* Accessible skip link — positioned off-screen until focused */}
      <a href="#main" className="skip-link">
        Skip to main content
      </a>

      {/* ── Name corner / identity header ───────────────────────────────────── */}
      <header
        id="top"
        aria-label="Site identity"
        data-motion-hero
        style={{
          backgroundColor: 'var(--color-paper)',
          borderBottom: '1px solid var(--color-hairline)',
          padding: 'var(--space-6) var(--space-8)',
        }}
      >
        <div
          style={{
            maxWidth: 'var(--col-wide)',
            margin: '0 auto',
            display: 'flex',
            alignItems: 'baseline',
            gap: 'var(--space-4)',
          }}
        >
          <span
            aria-hidden="true"
            style={{
              fontFamily: 'var(--font-serif)',
              fontSize: 'var(--text-xs)',
              letterSpacing: 'var(--tracking-caps)',
              textTransform: 'uppercase',
              color: 'var(--color-muted)',
            }}
          >
            Portfolio
          </span>
          <h1
            data-identity
            style={{
              fontFamily: 'var(--font-serif)',
              fontSize: 'var(--text-2xl)',
              fontWeight: 400,
              letterSpacing: 'var(--tracking-tight)',
              color: 'var(--color-ink)',
              lineHeight: 'var(--leading-tight)',
              margin: 0,
            }}
          >
            {identity.name}
          </h1>
          <nav
            aria-label="Page sections"
            style={{
              marginLeft: 'auto',
              display: 'flex',
              gap: 'var(--space-6)',
            }}
          >
            {[
              ['About', '#about'],
              ['Selected work', '#selected-work'],
              ['Timeline', '#timeline'],
              ['Contact', '#contact'],
            ].map(([label, href]) => (
              <a
                key={label}
                href={href}
                style={{
                  fontFamily: 'var(--font-sans)',
                  fontSize: 'var(--text-sm)',
                  letterSpacing: 'var(--tracking-wide)',
                  textTransform: 'uppercase',
                  color: 'var(--color-muted)',
                  textDecoration: 'none',
                  transition: 'color var(--duration-base) var(--ease-out)',
                }}
                onMouseEnter={(e) => (e.currentTarget.style.color = 'var(--color-ink)')}
                onMouseLeave={(e) => (e.currentTarget.style.color = 'var(--color-muted)')}
              >
                {label}
              </a>
            ))}
          </nav>
        </div>
      </header>

      {/* ── Main content ────────────────────────────────────────────────────── */}
      <main id="main" tabIndex={-1}>
        <OpeningSpread />

        <SectionShell
          id="selected-work"
          label="Selected work"
          heading="Two pinned spreads"
          surface="surface"
          motionReveal
        >
          <SelectedWork works={selectedWork} />
        </SectionShell>

        <SectionShell
          id="timeline"
          label="Timeline"
          heading="Experience, education, leadership"
          surface="paper"
          motionReveal
        >
          <ExperienceTimeline
            experience={experience}
            education={education}
            leadership={leadership}
          />
        </SectionShell>
      </main>

      {/* ── Footer / colophon ───────────────────────────────────────────────── */}
      <footer
        id="contact"
        aria-label="Contact and colophon"
        data-motion-reveal
        style={{
          backgroundColor: 'var(--color-ink)',
          color: 'var(--color-faint)',
          padding: 'var(--space-12) var(--space-8)',
          textAlign: 'center',
        }}
      >
        <address
          style={{
            fontFamily: 'var(--font-sans)',
            fontSize: 'var(--text-sm)',
            fontStyle: 'normal',
            lineHeight: 'var(--leading-relaxed)',
            margin: '0 0 var(--space-6)',
          }}
        >
          <a href={`mailto:${contact.email}`} style={{ color: 'inherit' }}>
            {contact.email}
          </a>
          {' · '}
          <a href={contact.linkedin} style={{ color: 'inherit' }}>
            LinkedIn
          </a>
          {' · '}
          <a href={contact.github} style={{ color: 'inherit' }}>
            GitHub
          </a>
        </address>
        <p
          style={{
            fontFamily: 'var(--font-sans)',
            fontSize: 'var(--text-xs)',
            letterSpacing: 'var(--tracking-wide)',
            textTransform: 'uppercase',
            margin: 0,
          }}
        >
          {identity.name} &mdash; {new Date().getFullYear()}
        </p>
      </footer>
    </>
  );
}

